109	    /** Fixed city-to-region table used to derive an owner's locality. */
110	    private static final Map<String, String> CITY_REGION = Map.of(
111	        "Sydney", "NSW",
112	        "Melbourne", "VIC",
113	        "Brisbane", "QLD");
