115	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
116	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
117	        "NSW", new int[] {2000, 2099},
118	        "VIC", new int[] {3000, 3099},
119	        "QLD", new int[] {4000, 4099});
