127	    /**
128	     * Return the owner's address. When a structured address is supplied (a non-blank
129	     * {@code addressLine1}) it takes precedence and the value is composed as the
130	     * normalized {@code addressLine1}, with a single space and the normalized
131	     * {@code addressLine2} appended when an {@code addressLine2} is present.
132	     * Otherwise the flat {@code address} is returned, preserving backward
133	     * compatibility for owners supplied in the flat form.
134	     */
135	    public String getAddress() {
136	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
137	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
138	                return this.addressLine1 + " " + this.addressLine2;
139	            }
140	            return this.addressLine1;
141	        }
142	        return this.address;
143	    }
