145	    /**
146	     * Set the owner's flat address, normalizing it to a canonical form so it is both
147	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
148	     * internal runs of whitespace are collapsed to a single space, the value is
149	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
150	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
151	     * left as-is.
152	     */
153	    public void setAddress(String address) {
154	        this.address = normalizeAddress(address);
155	    }
