161	    /**
162	     * Set the first line of the owner's structured address, normalized the same way
163	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
164	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
165	     * as-is.
166	     */
167	    public void setAddressLine1(String addressLine1) {
