184	    /**
185	     * Normalize an address string to its canonical form: trimmed, whitespace
186	     * collapsed, upper-cased, with common street-type abbreviations expanded.
187	     * Returns {@code null} for a {@code null} input; a value that is blank once
188	     * trimmed normalizes to the empty string.
189	     */
190	    public static String normalizeAddress(String address) {
191	        if (address == null) {
192	            return null;
193	        }
194	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
195	        if (collapsed.isEmpty()) {
196	            return "";
197	        }
198	        String[] tokens = collapsed.split(" ");
199	        StringBuilder sb = new StringBuilder();
200	        for (int i = 0; i < tokens.length; i++) {
201	            if (i > 0) {
202	                sb.append(' ');
203	            }
204	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
205	        }
206	        return sb.toString();
207	    }
