225	    /**
226	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
227	     * country code, a space, then the national digits grouped in threes and separated
228	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
229	     * North American country code ({@code '+1'}) is one digit; other country codes are
230	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
231	     * raw value unchanged when it is not a well-formed E.164 number.
232	     */
233	    public String getTelephoneDisplay() {
234	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
235	            return this.telephone;
236	        }
237	        String digits = this.telephone.substring(1);
238	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
239	        if (digits.length() <= countryCodeLength) {
240	            return this.telephone;
241	        }
242	        String countryCode = digits.substring(0, countryCodeLength);
243	        String national = digits.substring(countryCodeLength);
244	        StringBuilder sb = new StringBuilder("+").append(countryCode);
245	        for (int i = 0; i < national.length(); i += 3) {
246	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
247	        }
248	        return sb.toString();
249	    }
