299	    /**
300	     * Return the owner's age band derived from the birth date, computed against the
301	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
302	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
303	     * either the birth date or the registration date is not set.
304	     */
305	    public String getAgeBand() {
306	        if (this.birthDate == null || this.registrationDate == null) {
307	            return null;
308	        }
309	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
310	        if (age < 18) {
311	            return "MINOR";
312	        }
313	        if (age < 65) {
314	            return "ADULT";
315	        }
316	        return "SENIOR";
317	    }
