327	    /**
328	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
329	     * is always valid (postcode is optional). When present, a postcode is valid if
330	     * the city has no known region, or if it is four digits falling within the
331	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
332	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
333	     */
334	    public boolean isPostcodeValidForCity() {
335	        if (this.postcode == null) {
336	            return true;
337	        }
338	        String region = CITY_REGION.get(this.city);
339	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
340	        if (range == null) {
341	            return true;
342	        }
343	        if (!this.postcode.matches("^[0-9]{4}$")) {
344	            return false;
345	        }
346	        int value = Integer.parseInt(this.postcode);
347	        return value >= range[0] && value <= range[1];
348	    }
