358	    /**
359	     * Return a single Luhn check digit (0-9) computed over the digits contained in
360	     * the owner's customer code, or {@code null} when the customer code is not set.
361	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
362	     * first, following the standard Luhn algorithm.
363	     */
364	    public Integer getCheckDigit() {
365	        if (this.customerCode == null) {
366	            return null;
367	        }
368	        int sum = 0;
369	        boolean doubleDigit = true;
370	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
371	            char c = this.customerCode.charAt(i);
372	            if (c < '0' || c > '9') {
373	                continue;
374	            }
375	            int digit = c - '0';
376	            if (doubleDigit) {
377	                digit *= 2;
378	                if (digit > 9) {
379	                    digit -= 9;
380	                }
381	            }
382	            sum += digit;
383	            doubleDigit = !doubleDigit;
384	        }
385	        return (10 - (sum % 10)) % 10;
386	    }
387	
388	    /**
389	     * Return the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY}
390	     * is the last two digits of the fiscal year derived from the (business-day
391	     * adjusted) registration date. The fiscal year starts on 1 July and is named
392	     * after the calendar year in which it ends, so a registration date on or after
393	     * 1 July belongs to the fiscal year ending the following calendar year (for
394	     * example {@code 2026-08-14 -> 'FY27'}), while a date before 1 July belongs to
395	     * the fiscal year ending in that same calendar year. Returns {@code null} when
396	     * the registration date is not set.
397	     */
398	    public String getFiscalYear() {
399	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
400	        if (fiscalYear == null) {
401	            return null;
402	        }
403	        return String.format("FY%02d", fiscalYear % 100);
404	    }
405	
406	    /**
407	     * Return the fiscal year (the calendar year in which the fiscal year ends) that
408	     * the given date falls in, where the fiscal year starts on 1 July, or
409	     * {@code null} when the date is {@code null}.
410	     */
411	    private static Integer fiscalYearOf(LocalDate date) {
412	        if (date == null) {
413	            return null;
414	        }
415	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
416	    }
