418	    /**
419	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
420	     * where {@code YY} is the last two digits of the fiscal year derived from the
421	     * registration date (for example {@code 'SMI-0007-M27'}). Returns {@code null}
422	     * when either the customer code or the registration date is not set.
423	     */
424	    public String getMembershipNumber() {
425	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
426	        if (this.customerCode == null || fiscalYear == null) {
427	            return null;
428	        }
429	        return String.format("%s-M%02d", this.customerCode, fiscalYear % 100);
430	    }
