559	    /**
560	     * Return the owner's locality (region), preferring the postcode: when the
561	     * postcode is present and falls within a known region's inclusive range
562	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
563	     * region is returned. Otherwise the value falls back to the fixed
564	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
565	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
566	     * table. This yields the same region for known cities but disambiguates
567	     * cities that share a name.
568	     */
569	    public String getLocality() {
570	        String regionFromPostcode = regionForPostcode();
571	        if (regionFromPostcode != null) {
572	            return regionFromPostcode;
573	        }
574	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
575	    }
576	
577	    /**
578	     * Return the owner's IANA timezone, derived from the locality/region via the
579	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
580	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
581	     * {@code null} when the region is not in the table.
582	     */
583	    public String getTimezone() {
584	        return REGION_TIMEZONE.get(getLocality());
585	    }
586	
587	    /**
588	     * Look up the region whose inclusive postcode range contains this owner's
589	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
590	     * known range.
591	     */
592	    private String regionForPostcode() {
593	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
594	            return null;
595	        }
596	        int value = Integer.parseInt(this.postcode);
597	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
598	            int[] range = entry.getValue();
599	            if (value >= range[0] && value <= range[1]) {
600	                return entry.getKey();
601	            }
602	        }
603	        return null;
604	    }
