606	    /**
607	     * Return the owner's preferred contact channel, derived from the stored
608	     * contact details: {@code 'EMAIL'} when an email address is present,
609	     * otherwise {@code 'PHONE'}.
610	     */
611	    public String getContactPreference() {
612	        boolean hasEmail = this.email != null && !this.email.isBlank();
613	        return hasEmail ? "EMAIL" : "PHONE";
614	    }
