616	    /**
617	     * Return the owner's derived identity key, which consolidates all duplicate
618	     * detection into a single value formed as
619	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
620	     * The telephone and email are already stored in their normalized (E.164 /
621	     * lower-cased) forms; a missing email or household id contributes an empty
622	     * segment. A create is rejected only when a new owner's whole identity key
623	     * equals an existing owner's.
624	     */
625	    public String getIdentityKey() {
626	        String telephonePart = this.telephone == null ? "" : this.telephone;
627	        String emailPart = (this.email == null) ? "" : this.email;
628	        String householdPart = (this.householdId == null) ? "" : this.householdId;
629	        return telephonePart + "|" + emailPart + "|" + householdPart;
630	    }
